2 tbsp dark rum
1/4 cup sugar
1 cup heavy cream
Sweetened whipped cream, for serving (optional)
Pastry leaves for garnish (optional; see [Pate Brisee recipe](http://www.xanthir.com/recipes/showrecipe.php?id=id101))',
