1 teaspoon vanilla extract
2 ounce semisweet chocolate, chopped
2 tablespoon unsalted butter
1 tablespoon light corn syrup
1 cup granulated sugar
3 egg whites
1/4 teaspoon cream of tartar
Pinch of salt
2 teaspoon vanilla extract',
