    '1. Slice mozzarella cheese into eight rounds about 1/2 in. thick. Place flour in first shallow dish. Lightly beat egg in second dish. Combine pecans, Parmesan cheese and bread crumbs in third dish. Lightly dredge each mozzarella round in flour, shaking off excess; dip into egg and then into pecan mixture, coating evenly.

