    'Heat oven to 425 degrees. In a mixing bowl whisk together all dry ingredients. In a small bowl mix together all wet ingredients. Pour the wet ingredients into the dry ingredients and mix together thoroughly with a fork into a wet batter. Place a heavy-bottomed oven-safe skillet or cast iron pan with 2 tablespoons butter in it into the preheated oven for 5 minutes. Allow the butter to get hot enough to sizzle when a drop of water is flicked into the pan. Holding the hot pan with an oven mitt pour the millet bread batter into the pan and spread it evenly around the pan. Place back in the oven and bake for 18-20 minutes until golden brown and a toothpick inserted in the middle comes out clean. Let cool for 10 minutes before serving.
',
