1 onion, halved
2 clove garlic, roughly chopped
1 tbsp ginger, roughly chopped
salt
1 teaspoon turmeric
1 teaspoon garam masala
20 ounce frozen peas
1 teaspoon tomato puree
1 cup vegetable stock',
