    55.0,
    20.0,
    'Prepare the ingredients:
Peel the plantain; Halve the rolls.Peel and thinly slice the shallot.Peel the plantain; cut on an angle into ¼-inch-thick pieces.Thinly slice the cheese.Cut off and discard the ends of the radishes; thinly slice into rounds.Peel and large dice the tangelo.Cut off and discard the root end of the romaine; roughly chop the leaves.Finely chop the peppers.

Marinate the shallot:
In a medium bowl, combine the shallot, sugar and vinegar; drizzle with olive oil and season with salt and pepper. Set aside to marinate, stirring occasionally, for at least 10 minutes. Season with salt and pepper to taste.

Cook the plantain:
While the shallot marinates, in a large pan (nonstick, if you have one), heat 1 teaspoon of olive oil on medium-high until hot. Add the plantain and season with salt and pepper. Cook 3 to 4 minutes on the first side, or until browned. Flip and cook 2 to 3 minutes, or until browned and softened. Transfer to a paper towel-lined plate and immediately season with salt and pepper. Wipe out the pan.

Assemble the tortas:
Place the rolls on a clean, dry work surface. Top the roll bottoms with the cheese, cooked plantain, peppers and marinated shallot (reserving the liquid). Season with salt and pepper. Complete the tortas with the roll tops.

Cook the tortas:
In the same pan, heat 2 teaspoons of olive oil on medium until hot. Add the tortas. Place a heavy-bottomed pot (or pan) on top of the tortas; press down. Cook, occasionally pressing down on the pot, 2 to 3 minutes per side, or until lightly browned and slightly flattened. Transfer to a cutting board.

Make the salad & plate your dish:
In a large bowl, combine the radishes, tangelo and romaine; season with salt and pepper. Add the reserved shallot marinating liquid and a drizzle of olive oil; toss to thoroughly combine. Season with salt and pepper to taste. Cut the cooked tortas in half on an angle. Divide the tortas and salad between 2 dishes. Enjoy!',
