2 teaspoon sugar
4 tablespoon butter, cold
1 cup cheddar cheese, very coarsely grated or diced
1/3 cup fresh chives, snipped
1/2 pound bacon, cooked, cooled, and crumbled (about 1 cup)
3/4 cup heavy cream, or enough to make the dough cohesive
2 tablespoon heavy cream',
