2 Rainbow Carrots, thinly sliced at an angle
1 1/2 Tbsp Rice Vinegar
1 1/2 Tbsp Sugar
1 Tbsp Gochujang
1 Tbsp Mirin
1 Tbsp Soy Sauce
1 tsp Furikake
1/4 cup Tempura Mix',
