    'Heat oil in medium pot. Add half the ginger and half the sesame seeds; cook 1-2 minutes until seeds are golden brown. Add rice, water, and a pinch of salt; bring to boil, then cover and simmer on low for 12-15 minutes until cooked. Keep covered off heat until ready to serve.

Mix mayonnaise, sriracha, and a small amount of water, to achieve a drizzling consistency.

In large bowl, whisk eggs and vegetable stock, then whisk in tempura mix until no lumps remain. Fold in cabbage, garlic, scallion whites, other half of ginger, and salt; mix thoroly.

Heat a large drizzle of oil in a medium pan, over medium-high heat. When pan is hot enough to immediately sizzle a drop of batter, add half the batter (for 2 servings). Cook for 2-4 minutes on each side, following pancake rules, then transfer to cutting board while preparing additional fritters.

