    'Preheat oven to 475F.

Heat a large pan with olive oil to medium heat. Arrange the eggplant in a single layer, and cook without stirring 2-3 minutes, until lightly browned. Add chives and half the garlic, season. Cook 1-2 minutes until softened. Add tomato paste and water, and cook 1-2 minutes, stirring frequently, until dark red and fragrant.

