1 Tbsp white wine vinegar
1 Tbsp honey
1 bird''s eye chile pepper, thinly sliced
2 Tbsp soy sauce
3 Tbsp sweet chili sauce
2 clove black garlic, peeled and roughly chopped
2 eggs',
