    'To a medium pot over medium heat add **sesame oil**. Add the **garlic**, **ginger**, **onion**, and the whites of the **green onions**, and sauté for 3-4 minutes until softened.

Add in the **vegetable stock paste**, **miso**, **coconut milk** and **Zhong Sauce**, stir just to combine and then pour in the water, stirring or whisking constantly to combine.

