4 oz grape tomatoes, halved
1 lime, zested and juiced
1/2 tsp olive oil
2 clove garlic, roughly chopped
1/2 can black beans, drained
1 tsp Mexican spice blend
3 tbsp water
1 tbsp creme fraiche
2 tbsp pumpkin seeds, toasted, for garnish',
