    'Whisk together **sour cream** and 2/3 of the **whipping cream** in medium saucepan. Gradually add **sugar**, whisking with each addition. Cook over low heat until warm, whisking often.

Sprinkle **gelatin** over 1/2 cup cold water in small saucepan, and let stand 1 min. Stir over med heat until gelatin dissolves, add to sour cream mixture.

