    0.0,
    'Remove any wilted outer leaves from the cabbages. Cut cabbages in half. On each half, slit the core thru most of the way up, so the leaves are loose but still attached.

Opening the leaves one by one, rub salt in, focusing on the thicker stem area. Close cabbage halves back up and let sit at room temperature for 2 hours, until the stems become tender/floppy. (Don''t let them sit too long and absorb too much salt.)

Split the cores along the slit so you have quarters. Rinse the salt off the leaves, then trim *most* of the core out, leaving just enough to keep the leaves together. (Or remove the core entirely, depending on how you want to present it.) Rinse again, and let drain.

----------

Mix the water, sugar, and flour in a small pot, and cook over medium heat for about 10 minutes, until it''s fully integrated and bubbling. Remove from heat, put in a large bowl, and let cool completely.

Once cooled, add all the spices and mix into a thin paste. Add the vegetables and mix well.

Rub the paste fully over each cabbage leaf. When a quarter is fully coated, wrap it around itself into a little packet, and put it into your storage container.

Let the kimchi ferment at room temperature for a day or two. When ready, it will start to smell and taste sour, and release bubbles when pressed on. If using a sealed jar, remember to open it occasionally to release pressure. Move the container to the refrigerator to slow the fermentation, where it can be stored about two weeks. It will get more sour as time goes on.',
    '6 lb napa cabbage
1/2 cup salt
2 cup water
2 tbsp glutinous rice flour
2 tbsp sugar
2 cup daikon (or Korean radish), matchsticks
1 cup carrot, matchsticks
8 green onions, chopped
