    0.0,
    0.0,
    'Mix all crust ingredients in a bowl. Pour into a 9" pie plate and press evenly on the bottom and sides. Refrigerate at least 30 minutes (or freeze for 10) before filling.

Add softened butter, peanut butter, powdered sugar, and salt to a large mixing bowl or the bowl of a stand mixer. Beat on low speed until smooth and creamy. Fold in the whipped cream. Spoon the peanut butter mixture over the crust into a smooth layer. Place back in freezer.

Place chocolate chips, remaining peanut butter, and salt in a large glass or heat-proof bowl. In a saucepan, bring heavy whipping cream to a rolling simmer over medium-high heat. Pour the cream over the chocolate chips and peanut butter and let sit for 5 minutes, then whisk until completely smooth. Pour the chocolate layer over the peanut butter layer. Sprinkle with flaky sea salt. Refrigerate, covered, at least 1 hour until ready to serve.

Expert suggestion: divide the chocolate in half, putting half into the crust first, chilling, then doing the peanut butter filling, chilling, then finally using the other half on top. This produces  thinner, more tender chocolate layers, but the chocolate amounts are low enough that it takes some skill to get it spread evenly without mixing with the crust or the filling.',
