Slap pizza directly on grill grate when ready. If bottom of pizza was oiled, you can remove the paper immediately; otherwise, it''s probably stuck, just leave it on. Close grill, cook for 5 minutes.

Remove from heat, flipping onto a cutting board. You can remove the paper now, if it was previously stuck; it should easily come off. Dress the now-grilled surface with any meltable cheeses and cookable toppings; do *not* sauce yet. Put back into grill, close, and cook for 4 minutes.

