    '7f76344d-b80d-50a2-842e-c362db7353ce',
    'Okra with ginger soy sauce',
    'Recipes',
    108.0,
    8.0,
    20.0,
    4.0,
    8.0,
    'Gather all the ingredients. Bring a medium pot of water to a boil over medium-high heat.

To Make the Ginger Soy Sauce
In a large bowl, combine **soy sauce** and the **grated ginger**. Taste it and add more grated ginger or ginger juice (which has a milder taste than the ginger bits) if desired. Set aside.

To Prepare the Okra
With a knife, cut off the stems of the **okra** but **don‘t remove the entire top**. Then, peel off the tough calyx around the top of the okra.

Sprinkle **kosher salt** over the okra and rub them between your hands and the cutting board (or tray) for 15–20 seconds. You don‘t need to rinse the salt.

The water should be boiling by now. Blanch the okra in the boiling water for 2–3 minutes. If the okra are small, blanch them for 1–2 minutes. If they are big, blanch for 3–4 minutes. Drain the okra in a sieve as soon as they are tender. Be careful not to overcook.

To Dress the Okra
Cut the **okra** diagonally in half or thirds depending on their length. They should be bite-sized pieces. Transfer the okra to the bowl with the **ginger soy sauce**.

Dress the okra with the sauce. You can serve them chilled or at room temperature. Serve the okra on individual plates.

To Store
You can keep the leftovers in an airtight container and store in the refrigerator for up to 2 days.',
    '9 oz okra
1 tsp kosher salt
2 tbsp soy sauce
1/2 tsp ginger, grated or minced with juice',
