1 tsp garlic powder
1 tbsp flour
1.5 oz tomato paste
3/4 cup water
2 tsp vegetable stock concentrate
2 tbsp sour cream
1/2 cup white cheddar, shredded, divided
2 tbsp butter
Olive oil
Salt and pepper',
