    0.0,
    0.0,
    'Cook rice. If fresh, spread it out to cool/dry for five minutes; ideally, cook the day before and cool in the fridge.

In a wok, heat 1 tbsp oil over high heat until just smoking. Add onion whites and cook, undisturbed, until charred, about 1 minute. Add cabbage and cook, stirring continuously, until wilted and charred, about 2 minutes. Transfer to a large bowl; set aside.

Reduce heat to medium-high and add chorizo to skillet. Cook, breaking up meat with a wooden spoon, until well browned, 6 to 8 minutes. Transfer to bowl with cabbage, leaving the fat in skillet.

If skillet is dry, add 1 tbsp of oil. Add rice and cook, stirring and tossing frequently, until it is pale brown and toasted, with a lightly chewy texture, about 3 minutes. Add garlic and cook until fragrant and softened, about 1 minute.

Return cooked onion whites, cabbage, and chorizo to skillet. Add pickled jalapeños and a tablespoon of reserved pickling liquid. Toss to combine. If needed (probably not, taste first), season with salt. Dish out to bowls, sprinkle with cotija and onion greens.',
