    '263b9404-5653-56dc-8fad-155b821e7981',
    'Sweet and Spicy Tofu With Soba Noodles',
    'Recipes',
    2173.0,
    94.0,
    279.0,
    82.0,
    24.0,
    'Step 1
Bring a small pot of water to a boil for the soba noodles.

Step 2
Cut tofu into 1-inch cubes. Heat a cast-iron skillet over medium-high heat. Add the vegetable oil and sesame oil. When the oil shimmers, add the tofu in a single layer, in batches if needed and cook until golden on all sides, turning as needed when the tofu releases easily from the pan, about 8 to 10 minutes total. Lift the tofu out of the pan with a spatula and transfer to a new paper-towel-lined plate.

Step 3
Meanwhile, cook the soba in boiling water for 5 to 8 minutes (or according to package directions), until just al dente, stirring frequently. Drain and rinse in cold water until the noodles no longer feel sticky.

Step 4
Add garlic, ginger and whites of the onions to the skillet, along with the remaining sesame oil, reduce the heat to medium, and cook until the oil is fragrant, stirring constantly, about 1 minute.

Step 5
Add cooked and drained soba noodles to the pan, along with soy sauce, sugar, black pepper, red pepper and reserved green onions; toss together until the noodles are coated. Gently toss in the tofu until all the pieces are covered in the sauce.

Step 6
Remove from the heat, and sprinkle cucumber, radish and cilantro on top. Serve warm or at room temperature, with lime.',
